import {activityAdvice,comparePlans,changeEvidence,activityAccesses} from './planning.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:1}),$=id=>document.getElementById(id);
const table=(headers,rows)=>'<div class="scroll"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
export function createEnhancements(api){let renderedData=null,lastBrief='';
$('replan').onclick=()=>{try{const location=$('disruption-location').value,from=+$('disruption-from').value,to=+$('disruption-to').value,capacity=+$('disruption-capacity').value,activity=$('start-activity').value,start=+$('start-week').value;const exp={disruptions:location?[{location,from,to,capacity}]:[],startWeeks:activity?{[activity]:start}:{}};if(!location&&!activity)throw Error('Choose a capacity change or an activity start change first.');api.experiment(exp);}catch(e){$('experiment-error').textContent=e.message;}};
$('reset-baseline').onclick=()=>{api.reset();$('disruption-location').value='';$('start-activity').value='';$('disruption-location').onchange();$('experiment-error').textContent='';};$('show-baseline').onclick=()=>api.showMode('baseline');$('show-experiment').onclick=()=>api.showMode('experiment');
$('disruption-location').onchange=()=>{const {data}=api.state(),x=data?.['04_LOCATION_SUPPLY'].find(x=>x.location_id===$('disruption-location').value);if(x){$('disruption-capacity').max=x.supply_capacity;$('disruption-capacity').value=Math.max(0,+x.supply_capacity-1);$('capacity-hint').textContent='Original weekly supply: '+x.supply_capacity+'. This changes the access quota, not a full physical closure.';}else $('capacity-hint').textContent='Leave blank to test only an activity start change.';};
$('start-activity').onchange=()=>{const s=api.state(),a=s.baseline[s.scenario]?.modelInfo.activities.find(a=>a.id===$('start-activity').value);if(a)$('start-week').value=a.start;};
$('download-brief').onclick=()=>api.download('Controller_Brief_'+api.state().mode+'_'+api.state().scenario+'.txt',new Blob([lastBrief],{type:'text/plain'}));
document.addEventListener('click',e=>{const b=e.target.closest('[data-hotspot],[data-recommend-start],[data-switch-scenario],[data-inspect-change]');if(!b)return;const s=api.state();if(b.dataset.hotspot!==undefined)hotspot(+b.dataset.hotspot);if(b.dataset.switchScenario)api.selectScenario(b.dataset.switchScenario);if(b.dataset.inspectChange)api.inspect(b.dataset.inspectChange);if(b.dataset.recommendStart){$('start-activity').value=b.dataset.recommendStart;$('start-week').value=b.dataset.week;$('disruption-location').value='';$('disruption-location').onchange();$('experiment-panel').open=true;$('experiment-panel').scrollIntoView({behavior:'smooth'});$('experiment-error').textContent='Hypothetical change only. Run the comparison to check resources and predecessors.';}});
function render(){const s=api.state(),r=s.results[s.scenario],base=s.baseline[s.scenario],complete=['A','B','C'].every(k=>s.baseline[k]);$('planning-mode').textContent=s.mode==='baseline'?'SUBMISSION BASELINE':'WHAT-IF EXPERIMENT';$('mode-strip').classList.toggle('experiment-mode',s.mode==='experiment');$('show-baseline').classList.toggle('primary',s.mode==='baseline');$('show-experiment').classList.toggle('primary',s.mode==='experiment');$('show-experiment').disabled=s.busy||!Object.keys(s.experimental).length;$('show-baseline').disabled=s.busy;$('replan').disabled=s.busy||!complete;$('reset-baseline').disabled=s.busy||!Object.keys(s.experimental).length;for(const id of ['disruption-location','disruption-from','disruption-to','disruption-capacity','start-activity','start-week'])$(id).disabled=s.busy||!complete;$('run').textContent='Generate baseline schedules →';$('run').disabled=s.busy||!s.data;$('download-brief').disabled=s.busy||!r;
if(s.data&&renderedData!==s.data){renderedData=s.data;$('disruption-location').innerHTML='<option value="">No capacity change</option>'+s.data['04_LOCATION_SUPPLY'].map(x=>'<option value="'+esc(x.location_id)+'">'+esc(x.location_id)+'</option>').join('');$('start-activity').innerHTML='<option value="">No start-date change</option>'+s.data['08_ACTIVITY_DETAILS'].map(x=>'<option>'+esc(x.activity_id)+'</option>').join('');}
const changeText=s.experiment?[(s.experiment.disruptions||[]).map(x=>x.location+': capacity '+x.capacity+' in W'+x.from+'–'+x.to).join('; '),Object.entries(s.experiment.startWeeks||{}).map(([id,w])=>id+': earliest start W'+w).join('; ')].filter(Boolean).join(' · '):'';$('applied-changes').textContent=changeText?(s.mode==='experiment'?'Applied experiment: ':'Saved experiment: ')+changeText:'Baseline inputs are preserved. Experiments are separate and can be reset.';
if(!r){$('brief-content').innerHTML='<p class="muted">Generate the baseline to see delivery risks and recommended decisions.</p>';$('comparison-panel').hidden=true;return;}
const late=r.results.filter(x=>x.overrun_days>0),safe=r.report.feasible,others=s.results;let summary=safe?(late.length?late.map(x=>x.contract_number+' '+x.overrun_days+' days late').join('; ')+'.':'All planned contract dates met.'):'This candidate fails implemented checks; do not treat it as a submission-ready plan.';const approvals=[];if(r.report.eclo_nights_total)approvals.push(r.report.eclo_nights_total+' ECLO accesses require extended-hours approval');if(r.report.excess_access_nights_total)approvals.push(r.report.excess_access_nights_total+' extra location-week slots require additional access');if(late.length)approvals.push('accept or renegotiate the listed completion delays');if(s.mode==='experiment'&&Object.keys(s.experiment?.startWeeks||{}).length)approvals.push('earlier starts are hypothetical and require approval');
const comparisons=['A','B','C'].filter(k=>others[k]).map(k=>{const p=others[k].report;return k+': '+(p.feasible?'checks passed':'CHECKS FAILED')+', '+p.overrun_days_total+' contract-delay days, '+p.eclo_nights_total+' ECLO, '+p.excess_access_nights_total+' extra slots, '+fmt(p.objective_score)+' penalty';});
lastBrief=['TrackPlan controller briefing — '+s.mode+' — Scenario '+s.scenario,changeText,summary,'Complete activities: '+r.report.complete+'/'+r.report.total, ...comparisons,'Decisions: '+(approvals.join('; ')||'No additional access or deadline concession identified.'),'Scores measure different policies: B enforces deadlines; A/C may accept delay.','Checks are TrackPlan checks; the official validator has not been run.'].filter(Boolean).join('\n');
$('brief-content').innerHTML='<div class="brief-main"><strong>'+esc(summary)+'</strong><p>'+esc(approvals.length?'Decisions needed: '+approvals.join('; ')+'.':'No additional access or deadline concession identified.')+'</p></div><div class="brief-options">'+comparisons.map(x=>'<p>'+esc(x)+'</p>').join('')+'</div><p class="muted">B protects deadlines; A/C allow delay. A lower score across different policies does not automatically mean a better operational choice.</p>';
$('comparison-panel').hidden=!(s.mode==='experiment'&&base);if(s.mode==='experiment'&&base){const c=comparePlans(base,r),labels={objective_score:'Penalty',overrun_days_total:'Contract-delay days',eclo_nights_total:'ECLO accesses',excess_access_nights_total:'Extra location-week slots'};$('comparison-summary').innerHTML='<p><strong>'+c.changed.length+' activities changed; '+c.unchanged+' retained their weeks and ECLO settings.</strong> Feasibility and penalty take precedence; fewer changed activities break score ties. This is not a guarantee of minimum disruption.</p>'+table(['Measure','Baseline','Experiment','Change'],c.metrics.map(x=>[labels[x.key],fmt(x.before),fmt(x.after),(x.delta>0?'+':'')+fmt(x.delta)]));$('changes-table').innerHTML=c.rows.length?table(['Activity','Baseline weeks (* ECLO)','Revised weeks (* ECLO)','Finish week change'],c.rows.map(x=>['<button class="table-button" data-inspect-change="'+esc(x.id)+'">'+esc(x.id)+' · '+esc(x.contract)+'</button>',esc(x.before),esc(x.after),(x.afterFinish-x.beforeFinish>0?'+':'')+(x.afterFinish-x.beforeFinish)])):'<p class="info">The baseline remains feasible and no schedule changes were needed for this candidate.</p>';}
}
function inspect(id){const s=api.state(),r=s.results[s.scenario],d=activityAdvice(r,id),a=d.a,base=s.baseline[s.scenario],baselineA=s.baseline.A?.modelInfo.activities.find(x=>x.id===id);let html='<section class="recommendations"><h3>Options to improve delivery</h3><p>'+esc(d.standardFinish>a.due?'At the current start and predecessor dates, standard accesses cannot meet the target even without congestion. Earliest standard finish: W'+d.standardFinish+'.':d.late?'The workload can fit in isolation, but the selected schedule finishes late. Inspect the recorded deferrals and capacity constraints.':'This activity meets its target in the selected schedule. No recovery action is required.')+'</p><div class="recommendation-grid"><article><span class="badge">Current policy</span><h4>'+(!d.late?'Keep this placement':s.scenario==='B'?'Review failed deadline gate':'Accept the scheduled finish')+'</h4><p>'+esc(d.late&&s.scenario==='B'?'A late candidate is not valid for B. More search or revised inputs are needed.':'Scheduled finish: W'+d.finish+'. Safety and workload constraints still apply.')+'</p></article>';
if(d.earlierStart>=1&&baselineA&&d.earlierStart<baselineA.start){html+='<article><span class="badge">Requires input approval</span><h4>Test an earlier start</h4><p>In isolation, start by W'+d.earlierStart+' to fit '+Math.ceil(a.workload)+' standard accesses before W'+a.due+'. '+(d.predFinish&&d.predFinish>=d.earlierStart?'The current predecessor finish would also block this proposal. ':'')+'Re-run to check resource conflicts.</p><button data-recommend-start="'+esc(id)+'" data-week="'+d.earlierStart+'">Try as a what-if →</button></article>';}
html+='<article><span class="badge">Alternative policy</span><h4>Compare Scenario B</h4><p>'+esc(d.ecloCanFit?(d.minimumECLO?'At least '+d.minimumECLO+' ECLO accesses are needed in isolation within the '+d.available+' available weeks.':'No ECLO is required by the isolated workload calculation.'): 'ECLO alone cannot fit this workload into the available weeks at one access per week.')+' ECLO is forbidden in A; C has a two-week window per line. Resource checks still apply.</p><button data-switch-scenario="B">View calculated B plan →</button></article></div><p class="muted">Adding teams does not override the one-access-per-activity-per-week rule. Suggestions do not silently change your submission inputs.</p>';
const deferrals=r.decisions[id]||[];if(deferrals.length)html+='<details><summary>Recorded scheduling constraints ('+deferrals.length+' weeks)</summary>'+deferrals.map(x=>'<p>W'+x.week+': '+esc(x.reason)+(x.blockers?.length?' · Candidate-slot conflicts: '+esc(x.blockers.join(', ')):'')+'</p>').join('')+'</details>';
if(s.mode==='experiment'&&base)html+='<div class="info"><strong>Evidence behind the change</strong>'+changeEvidence(base,r,id).map(x=>'<p>'+esc(x)+'</p>').join('')+'<p class="muted">These are recorded constraints and input relationships, not proof of a unique cause.</p></div>';html+='</section>';$('inspector').insertAdjacentHTML('beforeend',html);}
function hotspot(index){const s=api.state(),r=s.results[s.scenario],h=r.report.hotspots[index];if(!h)return;const entries=r.occupancy.filter(x=>x.week===h.week&&x.location_id===h.location),ids=[...new Set(entries.map(x=>x.activity_id))];$('inspector').hidden=false;$('inspector').innerHTML='<div class="inspector-top"><div><p class="eyebrow">CAPACITY DETAIL · WEEK '+h.week+'</p><h2>'+esc(h.location)+'</h2></div><button id="close-hotspot">Close ×</button></div><p>'+h.used+' possession groups / '+h.capacity+' available slots · '+ids.length+' activities · '+h.excess+' extra slots. Co-sharing activities in the same group consume one slot here.</p>'+table(['Activity','Contract','Possession group','Type','Work nature'],ids.map(id=>{const a=r.modelInfo.activities.find(x=>x.id===id),o=entries.find(x=>x.activity_id===id);return ['<button class="table-button" data-inspect-change="'+esc(id)+'">'+esc(id)+'</button>',esc(a.contract),esc(o.co_share_group),esc(a.access_type),esc(a.nature)];}))+'<p class="info">Full capacity does not itself mean a violation. Scenario A permits no excess, B permits penalised excess, and C permits at most one extra slot per location-week.</p>';$('close-hotspot').onclick=()=>{$('inspector').hidden=true;};$('inspector').scrollIntoView({behavior:'smooth'});}
return{render,inspect};}
